package com.snaphere.api.auth;
import jakarta.validation.constraints.*;
final class AuthDtos { private AuthDtos(){} record GoogleLoginRequest(@NotBlank String idToken,@NotBlank String deviceId,@NotNull Platform platform,String fcmToken){} record OnboardingRequest(@NotBlank @Size(min=2,max=20) String nickname,@NotBlank String termsVersion,@NotBlank @Pattern(regexp="ko-KR|en-US|zh-CN|ja-JP") String locale){} record RefreshRequest(@NotBlank String refreshToken,@NotBlank String deviceId){} record RestoreAccountRequest(@NotBlank String restoreKey,@NotBlank @Size(min=2,max=20) String nickname,@NotNull Boolean confirmDataLoss){} record TokenBundle(String accessToken,long accessTokenExpiresIn,String refreshToken,long refreshTokenExpiresIn){} record AuthResult(TokenBundle tokens,UserView user,boolean onboardingRequired,boolean recoveryOffered,String restoreKey){} record UserView(String userId,String email,String nickname,String profileImageUrl,String status,String role,String locale){} }
